#!/usr/bin/env php
<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/bootstrap.php';require_once __DIR__.'/../includes/push_notifications.php';
$o=getopt('',['limit:','dry-run','notification-id:']);$limit=max(1,min(100,(int)($o['limit']??25)));$dry=isset($o['dry-run']);$nid=isset($o['notification-id'])?max(1,(int)$o['notification-id']):null;$cfg=push_config();$report=['mode'=>$dry?'dry-run':'send','synchronized'=>0,'claimed'=>0,'sent'=>0,'temporary_failures'=>0,'invalidated'=>0,'skipped'=>0];
if(!$cfg['enabled']){echo json_encode($report+['status'=>'disabled']).PHP_EOL;exit(0);}if(!$cfg['encryption_ready']||!$cfg['dependency_ready']||$cfg['vapid_public']===''||$cfg['vapid_private']===''||$cfg['vapid_subject']===''){fwrite(STDERR,json_encode($report+['status'=>'configuration-unavailable']).PHP_EOL);exit(2);}
$db=push_db();try{$report['synchronized']=push_synchronize($db,500,$nid,$dry);if($dry){$q="SELECT COUNT(*) FROM push_deliveries WHERE status IN ('pending','retry') AND COALESCE(next_attempt_at,datetime('now'))<=datetime('now')";$report['claimed']=min($limit,(int)$db->query($q)->fetchColumn());echo json_encode($report+['status'=>'ok']).PHP_EOL;exit(0);}
 $token=bin2hex(random_bytes(16));$db->exec('BEGIN IMMEDIATE');$lease=$db->prepare("INSERT INTO push_worker_leases(lease_key,lease_token,lease_expires_at,updated_at) VALUES('global',?,datetime('now','+2 minutes'),datetime('now')) ON CONFLICT(lease_key) DO UPDATE SET lease_token=excluded.lease_token,lease_expires_at=excluded.lease_expires_at,updated_at=excluded.updated_at WHERE push_worker_leases.lease_expires_at<datetime('now')");$lease->execute([$token]);$owned=$db->prepare("SELECT 1 FROM push_worker_leases WHERE lease_key='global' AND lease_token=?");$owned->execute([$token]);if(!$owned->fetchColumn()){$db->commit();echo json_encode($report+['status'=>'worker-busy']).PHP_EOL;exit(0);}$db->exec("UPDATE push_deliveries SET status='retry',claim_token=NULL,claim_expires_at=NULL,updated_at=datetime('now') WHERE status='claimed' AND claim_expires_at<datetime('now')");$sql="SELECT id FROM push_deliveries WHERE status IN ('pending','retry') AND COALESCE(next_attempt_at,datetime('now'))<=datetime('now')".($nid?' AND notification_id='.(int)$nid:'')." ORDER BY id LIMIT ".$limit;$ids=$db->query($sql)->fetchAll(PDO::FETCH_COLUMN);$claim=$db->prepare("UPDATE push_deliveries SET status='claimed',claim_token=?,claim_expires_at=datetime('now','+2 minutes'),attempt_count=attempt_count+1,updated_at=datetime('now') WHERE id=? AND status IN ('pending','retry')");foreach($ids as $id)$claim->execute([$token,$id]);$db->commit();$report['claimed']=count($ids);
 require __DIR__.'/../vendor/autoload.php';$wp=new Minishlink\WebPush\WebPush(['VAPID'=>['subject'=>$cfg['vapid_subject'],'publicKey'=>$cfg['vapid_public'],'privateKey'=>$cfg['vapid_private']]]);
 foreach($ids as $id){$owned->execute([$token]);if(!$owned->fetchColumn())break;$q=$db->prepare("SELECT d.*,p.user_id,p.endpoint_encrypted,p.p256dh_encrypted,p.auth_encrypted,n.notification_type,s.status notification_status,s.dismissed_at FROM push_deliveries d JOIN push_subscriptions p ON p.id=d.subscription_id JOIN portal_notifications n ON n.id=d.notification_id JOIN portal_notification_status s ON s.notification_id=n.id AND s.user_id=p.user_id WHERE d.id=? AND d.claim_token=? AND p.status='active'");$q->execute([$id,$token]);$row=$q->fetch(PDO::FETCH_ASSOC);if(!$row||$row['notification_status']!=='unread'||$row['dismissed_at']!==null){$u=$db->prepare("UPDATE push_deliveries SET status='skipped',skipped_at=datetime('now'),claim_token=NULL,claim_expires_at=NULL,updated_at=datetime('now'),last_failure_category='not_eligible' WHERE id=? AND claim_token=?");$u->execute([$id,$token]);$report['skipped']++;continue;}$copy=push_safe_copy((string)$row['notification_type']);if(!$copy){$report['skipped']++;continue;}$payload=json_encode($copy+['notification_id'=>(int)$row['notification_id'],'unread_count'=>min(99,push_unread_count($db,(int)$row['user_id']))]);$sub=Minishlink\WebPush\Subscription::create(['endpoint'=>push_decrypt($row['endpoint_encrypted']),'publicKey'=>push_decrypt($row['p256dh_encrypted']),'authToken'=>push_decrypt($row['auth_encrypted']),'contentEncoding'=>'aes128gcm']);$wp->queueNotification($sub,$payload);$result=null;foreach($wp->flush() as $one){$result=$one;break;}if(!$result)throw new RuntimeException('Push transport produced no report.');$code=(int)($result->getResponse()?->getStatusCode()??0);$db->beginTransaction();if($result->isSuccess()){$u=$db->prepare("UPDATE push_deliveries SET status='sent',sent_at=datetime('now'),updated_at=datetime('now'),claim_token=NULL,claim_expires_at=NULL,last_response_status=? WHERE id=? AND claim_token=?");$u->execute([$code?:201,$id,$token]);$report['sent']++;}elseif(in_array($code,[404,410],true)){$u=$db->prepare("UPDATE push_deliveries SET status='invalid',invalidated_at=datetime('now'),updated_at=datetime('now'),claim_token=NULL,claim_expires_at=NULL,last_response_status=?,last_failure_category='permanent' WHERE id=? AND claim_token=?");$u->execute([$code,$id,$token]);$db->prepare("UPDATE push_subscriptions SET status='expired',invalidated_at=datetime('now'),updated_at=datetime('now'),failure_count=failure_count+1,last_response_status=?,last_failure_category='permanent' WHERE id=?")->execute([$code,$row['subscription_id']]);$db->prepare("UPDATE push_deliveries SET status='skipped',skipped_at=datetime('now'),updated_at=datetime('now'),last_failure_category='subscription_inactive' WHERE subscription_id=? AND status IN ('pending','retry')")->execute([$row['subscription_id']]);$report['invalidated']++;}else{$attempt=(int)$row['attempt_count'];$terminal=$attempt>=PUSH_MAX_ATTEMPTS;$u=$db->prepare("UPDATE push_deliveries SET status=?,next_attempt_at=datetime('now','+".push_backoff_seconds($attempt)." seconds'),updated_at=datetime('now'),claim_token=NULL,claim_expires_at=NULL,last_response_status=?,last_failure_category='temporary' WHERE id=? AND claim_token=?");$u->execute([$terminal?'failed':'retry',$code?:null,$id,$token]);$report['temporary_failures']++;}$db->commit();}
 $db->prepare("DELETE FROM push_worker_leases WHERE lease_key='global' AND lease_token=?")->execute([$token]);echo json_encode($report+['status'=>'ok']).PHP_EOL;exit($report['temporary_failures']?1:0);
}catch(Throwable $e){fwrite(STDERR,json_encode($report+['status'=>'worker-failed']).PHP_EOL);exit(2);}
